-- =====================================================================
-- YOURMARKET SHOP — production release migration (schema + RLS + seed)
-- Generated by the release toolchain. Run ONCE against the project
-- database (Supabase SQL editor or `supabase db push`).
-- No service_role keys, no secrets, no destructive DDL.
-- =====================================================================

begin;
set search_path = public;


create table if not exists public.brands (
  id uuid primary key,
  name text not null,
  slug text,
  image text
);
create table if not exists public.categories (
  id uuid primary key,
  name text not null,
  slug text not null,
  description text,
  image text,
  display_order integer default 0,
  active boolean default true
);
create table if not exists public.subcategories (
  id uuid primary key,
  name text not null,
  slug text not null,
  category_id uuid not null references public.categories (id) on delete cascade,
  display_order integer default 0,
  active boolean default true
);
create table if not exists public.products (
  id uuid primary key,
  name text not null,
  slug text not null unique,
  brand_id uuid references public.brands (id),
  category_id uuid references public.categories (id),
  subcategory_id uuid references public.subcategories (id),
  price numeric not null default 0,
  sale_price numeric,
  short_description text,
  description text,
  background_display_text text,
  background_text_style text default 'bold',
  background_text_color text,
  featured boolean default false,
  new_arrival boolean default false,
  deal boolean default false,
  active boolean default true,
  created_at timestamptz default now()
);
create table if not exists public.product_variants (
  id uuid primary key,
  product_id uuid not null references public.products (id) on delete cascade,
  color_name text not null,
  color_value text not null,
  image text,
  transparent_image text,
  theme_color text,
  accent_color text,
  text_color text,
  display_order integer default 0,
  active boolean default true
);
create table if not exists public.variant_sizes (
  id uuid primary key,
  variant_id uuid not null references public.product_variants (id) on delete cascade,
  sku text,
  stock integer not null default 0,
  size_label text,
  label text
);
create table if not exists public.product_images (
  id uuid primary key,
  product_id uuid not null references public.products (id) on delete cascade,
  variant_id uuid references public.product_variants (id) on delete cascade,
  url text not null default '',
  image_url text,
  position integer default 0,
  is_main boolean default false
);
create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  full_name text,
  phone text,
  avatar_url text,
  date_of_birth date
);
create table if not exists public.cart_items (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  product_id uuid not null,
  variant_id uuid,
  size text,
  quantity integer not null default 1,
  created_at timestamptz default now()
);
create table if not exists public.wishlist_items (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  product_id uuid not null,
  created_at timestamptz default now()
);
create table if not exists public.addresses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  label text,
  full_name text,
  street text,
  city text,
  country text,
  phone text,
  is_default boolean default false
);
create table if not exists public.orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null unique,
  user_id uuid not null references auth.users (id) on delete cascade,
  subtotal numeric not null default 0,
  discount numeric not null default 0,
  shipping numeric not null default 0,
  tax numeric not null default 0,
  total_amount numeric not null default 0,
  total numeric not null default 0,
  payment_method text not null,
  payment_status text not null default 'pending',
  status text not null default 'new',
  shipping_address jsonb,
  coupon_id uuid,
  created_at timestamptz default now()
);
create table if not exists public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  product_id uuid,
  variant_id uuid,
  product_name text not null,
  product_slug text,
  variant_color_name text,
  variant_color_value text,
  image_url text,
  size text,
  quantity integer not null default 1,
  unit_price numeric not null default 0,
  line_total numeric not null default 0
);
create table if not exists public.order_status_history (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  status text not null,
  note text,
  created_at timestamptz default now()
);
create table if not exists public.coupons (
  id uuid primary key default gen_random_uuid(),
  code text not null unique,
  type text not null check (type in ('percentage','fixed')),
  value numeric not null default 0,
  min_order numeric,
  max_discount numeric,
  usage_limit integer,
  used_count integer not null default 0,
  start_date timestamptz,
  expiry_date timestamptz,
  active boolean default true
);
create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  title text not null,
  message text,
  read boolean default false,
  is_read boolean default false,
  created_at timestamptz default now()
);

