create or replace function public.decrement_stock(p_variant_size_id uuid, p_quantity integer)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare v_updated integer;
begin
  if p_variant_size_id is null or p_quantity is null or p_quantity < 1 then
    return false;
  end if;
  update public.variant_sizes
     set stock = stock - p_quantity
   where id = p_variant_size_id
     and stock >= p_quantity;
  get diagnostics v_updated = row_count;
  return v_updated = 1;
end;
$$;

revoke all on function public.decrement_stock(uuid, integer) from public;
grant execute on function public.decrement_stock(uuid, integer) to authenticated, anon;

